// spec: .qa/e2e/specs/stories-audience.md 2.1–2.2 · кейсы .qa/tests/stories-audience/SA-02, SA-03 · тикет #a85b92
// Только чтение: сторис не создаёт. reg1 — мужчина, религиозный, хочет женщин; reg2 — женщина, религиозная, хочет мужчин.
// Не проверен на живой странице (записан 10.11 без прогона). Вход reg1 в вебе сгорел 10.11 — перед прогоном qa-login:manual -- reg1.
import { test, expect } from '../../fixtures';
import { captureApi, asGuest, restGet } from '../_shared/api';
import { openDiscover, type FeedStory } from '../stories-viewer/viewer-helpers';
import { saveSession } from '../_shared/session';

test.describe('מנגנון חשיפת סיפורים לפי קהל — лента по аудитории', () => {
  test('reg1 (М→Ж) и reg2 (Ж→М) из одной аудитории — без общих авторов @iphone @prod-safe (#a85b92)', async ({ asUser }) => {
    const p1 = await asUser('reg1');
    const p2 = await asUser('reg2');
    try {
      const f1: FeedStory[] = await openDiscover(p1);
      const f2: FeedStory[] = await openDiscover(p2);
      const a1 = new Set(f1.map((s) => s.author_id));
      const a2 = new Set(f2.map((s) => s.author_id));
      expect(a1.size + a2.size, 'есть активные сторис хотя бы у одной ленты (иначе проверка пустая)').toBeGreaterThan(0);

      // AC 6: фильтр по полу / «רוצה להכיר» — одна и та же сторис не уходит обеим сторонам.
      const common = [...a1].filter((id) => a2.has(id));
      expect(common, 'общие авторы в лентах reg1 и reg2').toEqual([]);
    } finally {
      await saveSession(p1, 'reg1');
      await saveSession(p2, 'reg2');
    }
  });

  test('story_feed без входа — 401 @iphone @prod-safe (#a85b92)', async ({ asUser }) => {
    const p = await asUser('reg2');
    try {
      const api = await captureApi(p, '/discover');
      const res = await restGet(asGuest(api, p), 'story_feed?select=id&limit=1');
      // Чек-лист r8 п.3: «без токена 401».
      expect([401, 403], `story_feed без входа: ${res.status()} ${await res.text()}`).toContain(res.status());
    } finally {
      await saveSession(p, 'reg2');
    }
  });
});
